#!/usr/bin/env bash
# Phase 1: start the relay on :8080 with the demo keys from backend/.env.
# If backend/.env doesn't exist yet, it creates one with fresh demo-customer and
# other-agent keys. .env is gitignored, so keys are never committed.
#
# Usage: phases/phase-1/server.sh
source "$(dirname "${BASH_SOURCE[0]}")/../lib.sh"

ensure_built
load_env
if [ -z "${LILD_API_KEYS:-}" ]; then
  fresh_demo_keys
  umask 077
  cat >"$ENV_FILE" <<EOF
# Demo keys (generated by phases/phase-1/server.sh). Never commit this file.
LILD_API_KEYS=$LILD_API_KEYS
CUSTOMER_KEY=$CUSTOMER_KEY
OTHER_KEY=$OTHER_KEY
EOF
  echo "Created $ENV_FILE with fresh demo keys."
fi

echo "Starting relay on ${LILD_BIND:-127.0.0.1:8080} (Ctrl+C to stop)"
cd "$BACKEND"
exec env LILD_API_KEYS="$LILD_API_KEYS" ./target/debug/lild-backend
